// Code snippet to check if a target domain is a subdomain of the given domain
function isSubdomain(targetDomain, domain) {
  const domainParts = domain.split('.');
  const targetParts = targetDomain.split('.');

  if (targetParts.length < domainParts.length) {
    return false;
  }

  // Check if the target domain is a subdomain by matching the domain part
  const subdomainPart = targetParts.slice(0, targetParts.length - domainParts.length).join('.');
  const domainPart = targetParts.slice(targetParts.length - domainParts.length).join('.');

  return subdomainPart && subdomainPart !== '' && domainPart === domain;
}

// Example usage
console.log(isSubdomain('music.example.com', 'example.com')); // true
console.log(isSubdomain('example.com', 'example.com')); // true
console.log(isSubdomain('blog.example.com', 'example.com')); // true
console.log(isSubdomain('another.com', 'example.com')); // false

